import xml.etree.ElementTree as ET
tree = ET.parse('inputs/pytest.xml')
root = tree.getroot()
for testcase in root.iter('testcase'):
    for child in testcase:
        if child.tag in ('failure', 'skipped'):
            print(f'{child.tag.upper()}: {testcase.attrib.get(\"classname\")}.{testcase.attrib.get(\"name\")}')
            print(f'  Message: {child.attrib.get(\"message\")}')
